/* =========================================================================
 * OneCloud Server-Side Consent (SSC) clientlib
 * =========================================================================
 *
 * Loaded synchronously in <head> on every publish page (AEMaaCS) when the
 * SSC subsystem is enabled. Does two things, in order:
 *
 *   1. Always publishes `window.serverSideConsent.hasConsent` (boolean).
 *      cookievalidator (v1+v2), 1DS, and Adobe Target read this contract
 *      synchronously during page-load to decide whether to drop tracking
 *      cookies. We MUST set it before those scripts initialize.
 *
 *   2. On in-scope pages with consent=true, writes the `oc_db_data`
 *      cookie (pointer-keyed), emits <meta name="awa-db-*"> tags for 1DS
 *      telemetry, and publishes firmographic profile attributes to
 *      `window.targetPageParamsAll` for Adobe Target at.js personalization.
 *
 * -------------------------------------------------------------------------
 * Wire contracts
 * -------------------------------------------------------------------------
 * #oc-cookie-consent-config   application/json (always emitted on publish)
 *   { "isInScope": <bool>,
 *     "cookieMaxAgeSeconds": <int>,
 *     "fieldMap"?: { "<JSON-pointer>": { "metaName1ds"?, "metaNameTarget"? } },
 *     "targetModes": [<string>...],
 *     "targetMboxName": <string>
 *   }
 *
 * #oc-cookie-consent-data     text/plain (resolved by Akamai ESI)
 *   One of:
 *     A) {"cookie":true}      ESI saw oc_db_data on the request; clientlib
 *                             reads the cookie itself from document.cookie.
 *                             Cookie value is NEVER echoed into the island.
 *     B) <lookup response>    Raw JSON from /msonecloudapi/cookieconsent/lookup
 *                             when in-scope and no cookie. Shape:
 *                             { hasConsent:bool, ...firmographic }
 *     C) <check response>     Raw JSON from /msonecloudapi/cookieconsent/check
 *                             when out-of-scope. Shape: { hasConsent:bool }.
 *     D) empty / non-JSON     ESI failure (timeout, 404). text/plain MIME
 *                             tolerates this; clientlib treats as no-op.
 *
 * Cookie format (this client owns oc_db_data):
 *   logical: { "c": 1, "<JSON-pointer-1>": <value-1>, ... }
 *      `c`  = consent bit (1 = consented, anything else = no consent)
 *      keys = the SAME JSON-pointer strings used in the config fieldMap,
 *             so reads do not require re-walking the lookup tree.
 *   wire:    encodeURIComponent(JSON.stringify(<logical>))
 *   attrs:   Max-Age=<config.cookieMaxAgeSeconds>; Path=/; Secure; SameSite=Lax
 *
 * Force-invalidation strategy: RENAME the cookie (and COOKIE_NAME below);
 * we do NOT carry a `_v` schema version.
 *
 * -------------------------------------------------------------------------
 * Behavior matrix (mirrored 1:1 by __tests__/serversideconsent.test.js)
 * -------------------------------------------------------------------------
 *   serverSideConsent.disabled === true        -> exit, hasConsent untouched
 *   no #oc-cookie-consent-data element         -> hasConsent=false, exit
 *   data-island empty / non-JSON               -> hasConsent=false, exit
 *
 *   Branch A  island = {"cookie":true}
 *     no oc_db_data on document.cookie         -> hasConsent=false, exit
 *     cookie unparseable                       -> warn, hasConsent=false
 *     cookie.c !== 1                           -> hasConsent=false, exit
 *     cookie.c === 1                           -> hasConsent=true
 *       + isInScope && fieldMap                -> emit <meta> tags
 *                                                  (NO cookie write-back)
 *
 *   Branch B/C  island = lookup or check response
 *     hasConsent=false                         -> hasConsent=false, exit
 *     hasConsent=true && !isInScope            -> hasConsent=true, no metas
 *     hasConsent=true && isInScope
 *         && resolvedCount === 0               -> hasConsent=true, no cookie
 *     hasConsent=true && isInScope
 *         && resolvedCount > 0                 -> emit metas + write cookie
 * ========================================================================= */
(() => {
    "use strict";

    /* ---- Type definitions --------------------------------------------- */

    /**
     * @typedef {object} FieldMapEntry
     * @property {string} [metaName1ds]    Optional `<meta name>` for 1DS (`awa-db-*`).
     * @property {string} [metaNameTarget] Optional profile parameter name for Adobe Target at.js (`profile.<value>`).
     */

    /**
     * Map keyed by RFC 6901 JSON Pointer (e.g. `/companyProfile/industry`)
     * pointing into the lookup response, with the meta-tag names that should
     * be emitted for the resolved value.
     * @typedef {Record<string, FieldMapEntry>} FieldMap
     */

    /**
     * @typedef {object} ConsentConfig
     * @property {boolean}   [isInScope]            Whether the current page/locale is in scope for firmographic enrichment.
     * @property {number}    [cookieMaxAgeSeconds]  Cookie Max-Age (defaults to {@link DEFAULT_COOKIE_MAX_AGE_SECONDS}).
     * @property {FieldMap}  [fieldMap]             Pointer -> meta-name map.
     * @property {string[]}  [targetModes]          Ordered list of Adobe Target integration strategies to execute.
     * @property {string}    [targetMboxName]       Mbox name for strategies that need one (sendNotifications, getOffers, getOffer).
     */

    /** @typedef {{cookie: true}} CookieFlagPayload */
    /**
     * @typedef {object} ConsentResponsePayload
     * @property {boolean} [hasConsent] Authoritative consent bit from the ESI lookup/check endpoint.
     */
    /** @typedef {CookieFlagPayload | ConsentResponsePayload} EmbeddedDataPayload */

    /**
     * Shape of the JSON payload encoded into `oc_db_data`. The `c` bit is
     * required; all other keys are RFC 6901 JSON Pointers cloned from the
     * config fieldMap.
     * @typedef {{c: 1} & Record<string, unknown>} ConsentCookiePayload */

    /* ---- Constants ----------------------------------------------------- */

    const COOKIE_NAME = "oc_db_data";
    const DEFAULT_COOKIE_MAX_AGE_SECONDS = 1800;
    /**
     * Soft warning threshold for the rendered Set-Cookie header length.
     *
     * RFC 6265bis §6.1 ("Limits") requires user agents to support cookies of at
     * least 4096 octets per cookie (full Set-Cookie line: name + value + all
     * attributes). All current major browsers (Chromium, Firefox, WebKit) cap
     * at exactly 4096 bytes. We warn at 4093 to leave a 3-byte safety margin
     * for the trailing CRLF and any server-appended attributes.
     *
     * @see https://datatracker.ietf.org/doc/html/draft-ietf-httpbis-rfc6265bis
     */
    const COOKIE_SIZE_WARN_BYTES = 4093;
    const CONFIG_SCRIPT_ID = "oc-cookie-consent-config";
    const DATA_SCRIPT_ID = "oc-cookie-consent-data";
    const LOG_PREFIX = "[OneCloud-SSC]";
    const CONSENT_BIT_KEY = "c";
    const CONSENT_BIT_VALUE = 1;
    /** Prefix for Adobe Target profile parameter keys (`"profile.<name>"`). */
    const TARGET_PROFILE_PREFIX = "profile.";
    /** Default mbox name for Target delivery API strategies. */
    const DEFAULT_MBOX_NAME = "target-global-mbox";

    /* ---- Helpers ------------------------------------------------------- */

    /**
     * Returns `true` when the value is a non-null, non-array object —
     * i.e., a plain object suitable for property enumeration.
     *
     * Used for defensive validation of config blocks, field map entries,
     * and parsed JSON results throughout the IIFE.
     *
     * @param {unknown} value
     * @returns {value is Record<string, unknown>}
     */
    const isPlainObject = (value) =>
        value != null && typeof value === "object" && !Array.isArray(value);

    /**
     * Decodes a URI-encoded string, returning the raw input unchanged when
     * the percent-encoding is malformed (e.g., `"50%+discount"`).
     *
     * Wraps the native `decodeURIComponent` with a `URIError` guard so
     * callers need not repeat the try-catch pattern.
     *
     * @param {string} encoded  URI-encoded string.
     * @returns {string}        Decoded string, or raw input on failure.
     */
    const safeDecodeURIComponent = (encoded) => {
        try {
            return decodeURIComponent(encoded);
        } catch {
            return encoded;
        }
    };

    /**
     * Resolves an RFC 6901 JSON Pointer against an object tree.
     *
     * Supports the two standard escapes: `~1` -> `/` and `~0` -> `~`.
     * Returns `undefined` for any null/missing intermediate segment so
     * callers can use a single `value == null` guard.
     *
     * @param {unknown} root         Tree to resolve against.
     * @param {string}  pointer      JSON Pointer (e.g. `/companyProfile/industry`).
     * @returns {unknown}            Resolved value, or `undefined` if not present.
     */
    const resolveJsonPointer = (root, pointer) => {
        if (root == null || typeof pointer !== "string") return undefined;
        if (pointer === "") return root;
        if (!pointer.startsWith("/")) return undefined;

        const rawSegments = pointer.slice(1).split("/");

        let current = /** @type {any} */ (root);
        for (const raw of rawSegments) {
            if (current == null || typeof current !== "object") return undefined;
            const segment = raw.replaceAll("~1", "/").replaceAll("~0", "~");
            if (!Object.prototype.hasOwnProperty.call(current, segment)) return undefined;
            current = current[segment];
        }
        return current;
    };

    /**
     * Reads a single cookie value by name from `document.cookie`.
     *
     * Returns the URL-encoded raw value as the browser stored it; callers
     * must `decodeURIComponent` before parsing.
     *
     * @param {string}      name  Cookie name (no trailing `=`).
     * @returns {string|null}     Raw URL-encoded value, or `null` if absent.
     */
    const readCookieByName = (name) => {
        const cookies = document.cookie ?? "";
        if (!cookies) return null;

        const prefix = `${name}=`;
        for (const part of cookies.split(";")) {
            const trimmed = part.trimStart();
            if (trimmed.startsWith(prefix)) {
                return trimmed.slice(prefix.length);
            }
        }
        return null;
    };

    /**
     * Parses an inline `<script>` JSON block into an object.
     *
     * Returns `null` when the element is absent, empty, unparseable, or
     * does not parse to an object (i.e. arrays, primitives). When
     * `warnOnFailure` is true each failure mode logs a `console.warn` so
     * authors notice misconfigured config blocks; inline data-block ESI
     * failures (Branch D) are routine and call this with `false`.
     *
     * @param {string}  elementId      DOM id of the `<script>` tag holding the JSON.
     * @param {boolean} warnOnFailure  Emit `console.warn` describing the failure mode.
     * @returns {object|null}          Parsed object, or `null` on any failure.
     */
    const parseInlineJsonScript = (elementId, warnOnFailure) => {
        const warn = (reason, error) => {
            if (!warnOnFailure) return;
            const message = `${LOG_PREFIX} Inline JSON script #${elementId} ${reason}; using defaults.`;
            error ? console.warn(message, error) : console.warn(message);
        };

        const element = document.getElementById(elementId);
        if (!element) { warn("not found"); return null; }

        const text = element.textContent?.trim() ?? "";
        if (!text) { warn("is empty"); return null; }

        try {
            const parsed = JSON.parse(text);
            if (isPlainObject(parsed)) return parsed;
            warn("did not parse to an object");
            return null;
        } catch (error) {
            warn("failed to JSON.parse", error);
            return null;
        }
    };

    /**
     * Appends a `<meta name="..." content="...">` tag to `<head>`.
     *
     * Uses `document.head.appendChild` (never `document.write`) so the
     * call is safe at any document `readyState`.
     *
     * @param {string} name
     * @param {string} content
     */
    const appendMetaTag = (name, content) => {
        const meta = document.createElement("meta");
        meta.name = name;
        meta.content = content;
        document.head.appendChild(meta);
    };

    /**
     * Emits the configured 1DS `<meta>` tag for one resolved firmographic value.
     *
     * @param {FieldMapEntry} entry
     * @param {unknown}       value  Coerced to `String` for the meta `content`.
     */
    const emitMetaTagsForEntry = (entry, value) => {
        if (entry.metaName1ds) appendMetaTag(entry.metaName1ds, String(value));
    };

    /**
     * Validates a fieldMap entry for use in the meta-emit pipeline.
     *
     * @param {string}  pointer
     * @param {unknown} entry
     * @returns {entry is FieldMapEntry}
     */
    const isValidFieldMapEntry = (pointer, entry) =>
        typeof pointer === "string"
        && pointer !== ""
        && isPlainObject(entry);

    /**
     * Walks a fieldMap, resolving each entry via `resolveValue`. For every
     * pointer that resolves to a non-nullish value, invokes `onResolved`.
     * Returns the count of entries that produced a value -- callers use
     * this to decide whether to write the cookie.
     *
     * @param {FieldMap} fieldMap
     * @param {(pointer: string) => unknown} resolveValue
     * @param {(pointer: string, entry: FieldMapEntry, value: unknown) => void} onResolved
     * @returns {number}
     */
    const forEachResolvedField = (fieldMap, resolveValue, onResolved) => {
        let resolvedCount = 0;
        for (const [pointer, entry] of Object.entries(fieldMap)) {
            if (!isValidFieldMapEntry(pointer, entry)) continue;
            const value = resolveValue(pointer);
            if (value == null || typeof value === "object") continue;
            onResolved(pointer, entry, value);
            resolvedCount++;
        }
        return resolvedCount;
    };

    /**
     * Writes the pointer-keyed `oc_db_data` cookie. Emits a soft-limit
     * warning if the serialized header exceeds {@link COOKIE_SIZE_WARN_BYTES};
     * this is purely diagnostic -- the browser will still accept the cookie.
     *
     * @param {ConsentCookiePayload} payload
     * @param {number}               maxAgeSeconds
     */
    const writeConsentCookie = (payload, maxAgeSeconds) => {
        const serialized = JSON.stringify(payload);
        const encoded = encodeURIComponent(serialized);
        const cookieHeader = `${COOKIE_NAME}=${encoded}; Max-Age=${maxAgeSeconds}; Path=/; Secure; SameSite=Lax`;
        document.cookie = cookieHeader;
        if (cookieHeader.length > COOKIE_SIZE_WARN_BYTES) {
            console.warn(
                `${LOG_PREFIX} Serialized cookie size ${cookieHeader.length} bytes `
                + `exceeds soft limit of ${COOKIE_SIZE_WARN_BYTES} bytes.`
            );
        }
    };

    /* ---- Adobe Target integration strategies ----------------------------- */

    /**
     * Extracts bare profile parameter names from the `"profile.<name>"` keyed
     * map used by {@link publishTargetParams} to build the
     * {@link TargetProfileDelivery}. at.js APIs that accept
     * `profileParameters` expect un-prefixed keys (e.g. `"db-industry"`),
     * whereas `targetPageParamsAll` expects the `"profile."` prefix.
     *
     * Per Adobe docs, `profileParameters` constraints:
     *   - Max 50 parameters
     *   - Name: non-blank, max 128 chars, must NOT start with "profile."
     *   - Value: string only, max 5000 chars (256 for some APIs)
     *
     * @param {Record<string, string>} prefixedParams  `"profile.<name>"` → value map.
     * @returns {Record<string, string>}               `"<name>"` → value map.
     */
    const stripProfilePrefix = (prefixedParams) => {
        /** @type {Record<string, string>} */
        const bare = {};
        for (const [key, val] of Object.entries(prefixedParams)) {
            const strippedKey = key.startsWith(TARGET_PROFILE_PREFIX)
                ? key.slice(TARGET_PROFILE_PREFIX.length)
                : key;
            bare[strippedKey] = val;
        }
        return bare;
    };

    /**
     * Converts the flat `"profile.<name>"` keyed map into the nested
     * `{"profile": {"<name>": value}}` format expected by
     * `targetPageParamsAll` per Adobe docs.
     *
     * Example:
     *   Input:  `{"profile.db-industry": "Tech", "profile.db-ec": "5000"}`
     *   Output: `{"profile": {"db-industry": "Tech", "db-ec": "5000"}}`
     *
     * @param {Record<string, string>} prefixedParams  `"profile.<name>"` → value map.
     * @returns {{profile: Record<string, string>}}    Nested profile object.
     */
    const nestProfileParams = (prefixedParams) => {
        return { profile: stripProfilePrefix(prefixedParams) };
    };

    /**
     * Normalizes the return value of a previously-defined `targetPageParamsAll`
     * (or `targetPageParams`) function into a plain object.
     *
     * Per Adobe docs, the function may return one of three formats:
     *   1. Ampersand-delimited string: `"p1=v1&p2=v2&p3=hello%20world"`
     *   2. Array of `"key=value"` strings: `["a=1", "b=2"]`
     *   3. Plain object: `{ "profile.db-industry": "Tech" }`
     *
     * This helper ensures defensive merge always operates on a plain object.
     *
     * @param {unknown} raw  Return value from a `targetPageParamsAll` call.
     * @returns {Record<string, string>}  Normalized flat key-value map.
     */
    const normalizeTargetParams = (raw) => {
        if (raw == null) return {};

        // Case 3: plain object — most common, return as-is
        if (isPlainObject(raw)) {
            return /** @type {Record<string, string>} */ (raw);
        }

        /** @type {Record<string, string>} */
        const result = {};

        // Case 2: array of "key=value" strings
        if (Array.isArray(raw)) {
            for (const entry of raw) {
                if (typeof entry !== "string") continue;
                const eqIdx = entry.indexOf("=");
                if (eqIdx > 0) {
                    result[entry.slice(0, eqIdx)] = entry.slice(eqIdx + 1);
                }
            }
            return result;
        }

        // Case 1: ampersand-delimited string ("p1=v1&p2=v2")
        if (typeof raw === "string" && raw.length > 0) {
            for (const pair of raw.split("&")) {
                const eqIdx = pair.indexOf("=");
                if (eqIdx > 0) {
                    const rawKey = pair.slice(0, eqIdx);
                    const rawVal = pair.slice(eqIdx + 1);
                    result[safeDecodeURIComponent(rawKey)] = safeDecodeURIComponent(rawVal);
                }
            }
            return result;
        }

        return result;
    };

    /**
     * Generates a unique notification ID for `sendNotifications`.
     *
     * Uses `crypto.randomUUID()` when available (modern browsers, secure
     * contexts). Falls back to a timestamp + random suffix for older
     * browsers or non-secure contexts (HTTP) where `crypto.randomUUID`
     * is undefined.
     *
     * @returns {string}  Unique ID string (<= 200 chars per Adobe docs).
     */
    const generateNotificationId = () => {
        if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
            return crypto.randomUUID();
        }
        return `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
    };

    /**
     * Runs the handler once `adobe.target` is available by listening for the
     * at.js `at-library-loaded` custom event. If at.js has already fired
     * (i.e. `adobe.target.getOffers` exists), the handler runs immediately.
     *
     * The handler is wrapped in a try-catch so errors thrown inside deferred
     * callbacks (which run outside the `publishTargetParams` try-catch)
     * are caught and logged rather than escaping as unhandled runtime errors.
     *
     * @param {() => void} handler
     */
    const whenAtJsReady = (handler) => {
        const safeHandler = () => {
            try {
                handler();
            } catch (e) {
                console.warn(`${LOG_PREFIX} Deferred Target strategy failed.`, e);
            }
        };
        if (window.adobe?.target?.getOffers) {
            safeHandler();
        } else {
            document.addEventListener("at-library-loaded", safeHandler, { once: true });
        }
    };

    /**
     * Pre-computed profile delivery payload passed to each Target strategy
     * by {@link publishTargetParams}. Built once per publish cycle so
     * strategies receive ready-to-use data without duplicating
     * transformations or config lookups.
     *
     * @typedef {object} TargetProfileDelivery
     * @property {Record<string, string>} prefixedProfileParams  Flat `"profile.<name>"` → value map (for `getOffer` and `targetPageParamsAll`).
     * @property {Record<string, string>} profileParameters      Bare `"<name>"` → value map (for `sendNotifications` and `getOffers`; matches Adobe's API field name).
     * @property {string}                 mboxName               Resolved mbox name (from config or {@link DEFAULT_MBOX_NAME}; matches Adobe's API field name).
     */

    /**
     * Map of supported Adobe Target integration strategies.
     *
     * Each strategy receives a {@link TargetProfileDelivery} with pre-computed
     * parameter formats and the resolved mbox name. Strategies focus solely on
     * calling their respective Adobe API — no inline transformations or config
     * lookups.
     *
     * @type {Record<string, (delivery: TargetProfileDelivery) => void>}
     */
    const TARGET_STRATEGIES = {
        /**
         * **targetPageParamsAll** — defines `window.targetPageParamsAll` so
         * at.js includes `profile.*` parameters in every mbox request.
         *
         * Preserves any previously-defined function via defensive merge.
         * The previous function may return a string, array, or object per
         * Adobe docs — {@link normalizeTargetParams} handles all three.
         *
         * Returns the nested `{"profile": {"key": "value"}}` format per
         * Adobe docs — at.js flattens this internally to `profile.key=value`
         * for the delivery API request.
         *
         * Closes over `delivery.prefixedProfileParams` (same object reference as
         * `window.serverSideConsent.target`), so property mutations
         * after SSC init are reflected in subsequent at.js mbox calls.
         *
         * Zero network overhead — piggybacks on at.js's own delivery API call.
         * Effective for mbox calls that fire AFTER SSC runs (SPA triggerView,
         * subsequent named mboxes). The initial page-load mbox may have
         * already fired by the time SSC defines this function.
         */
        targetPageParamsAll: (delivery) => {
            const previousFn = window.targetPageParamsAll;
            const sscParams = delivery.prefixedProfileParams;
            window.targetPageParamsAll = () => {
                const existing = typeof previousFn === "function"
                    ? normalizeTargetParams(previousFn())
                    : {};
                const sscProfile = nestProfileParams(sscParams);
                return Object.assign({}, existing, sscProfile);
            };
        },

        /**
         * **sendNotifications** — fires `adobe.target.sendNotifications()`
         * with `profileParameters` after at.js initializes (via the
         * `at-library-loaded` event).
         *
         * Updates the visitor profile on Target edge asynchronously (non-
         * blocking beacon). Profile data is available for the current page's
         * subsequent mbox calls and all future visits.
         *
         * Per Adobe docs (`sendNotifications` notification object):
         *   - `id`: required, string, <= 200 chars, must be unique
         *   - `type`: required, "click" or "display"
         *   - `timestamp`: required, number (ms since epoch)
         *   - `tokens`: required, array of strings
         *   - `profileParameters`: optional, string values only
         */
        sendNotifications: (delivery) => {
            whenAtJsReady(() => {
                window.adobe.target.sendNotifications({
                    request: {
                        notifications: [{
                            id: generateNotificationId(),
                            type: "display",
                            timestamp: Date.now(),
                            mbox: { name: delivery.mboxName },
                            tokens: [],
                            profileParameters: delivery.profileParameters
                        }]
                    }
                });
            });
        },

        /**
         * **getOffers** — fires `adobe.target.getOffers()` with
         * `profileParameters` on `execute.pageLoad` after at.js initializes.
         *
         * Sends profile data AND retrieves personalized content in a single
         * delivery API call. Adds latency — use only when current-page
         * personalization from firmographic attributes is required.
         *
         * Per Adobe docs (`getOffers` execute.pageLoad.profileParameters):
         *   - Max 50 parameters
         *   - Name: non-blank, max 128 chars, must NOT start with "profile."
         *   - Value: string only, max 256 chars
         *
         * The returned promise is intentionally caught and swallowed;
         * personalization failure must not break the page.
         */
        getOffers: (delivery) => {
            whenAtJsReady(() => {
                window.adobe.target.getOffers({
                    request: {
                        execute: {
                            pageLoad: { profileParameters: delivery.profileParameters }
                        }
                    }
                }).catch(() => { /* fire-and-forget */ });
            });
        },

        /**
         * **getOffer** — fires `adobe.target.getOffer()` (at.js 1.x/2.x)
         * with `profile.*` params on the global mbox after at.js initializes.
         *
         * Simpler callback-based API that accepts `profile.*`-prefixed keys
         * directly in the `params` object (no prefix stripping needed).
         * Sends profile data AND retrieves offers for the specified mbox.
         *
         * Per Adobe docs (`getOffer`):
         *   - `mbox`: required, string (mbox name)
         *   - `params`: optional, flat key-value object (profile params use
         *     `"profile.<name>"` prefix)
         *   - `success`: required, callback receiving offer array
         *   - `error`: required, callback receiving status + error string
         *
         * Both callbacks are no-ops — SSC uses `getOffer` purely to deliver
         * profile attributes to Target edge, not to render offers.
         *
         * @see https://experienceleague.adobe.com/en/docs/target-dev/developer/client-side/functions-overview/adobe-target-getoffer
         */
        getOffer: (delivery) => {
            whenAtJsReady(() => {
                window.adobe.target.getOffer({
                    mbox: delivery.mboxName,
                    params: delivery.prefixedProfileParams,
                    success: () => { /* fire-and-forget */ },
                    error: () => { /* fire-and-forget */ }
                });
            });
        }
    };

    /**
     * Publishes firmographic profile attributes to Adobe Target using the
     * strategies configured in the Settings CF `target.modes` array.
     *
     * Pre-computes both parameter formats and the resolved mbox name into
     * a {@link TargetProfileDelivery} so strategies receive ready-to-use
     * data — no inline transformations, no repeated config lookups.
     *
     * Always populates `window.serverSideConsent.target` as a stable data
     * namespace consumed by downstream code and the `targetPageParamsAll`
     * strategy's closure.
     *
     * @param {Record<string, string>} targetParams  Flat map: `"profile.<name>"` → string value.
     * @param {ConsentConfig}          consentConfig  Parsed config data-island.
     */
    const publishTargetParams = (targetParams, consentConfig) => {
        if (Object.keys(targetParams).length === 0) return;

        window.serverSideConsent.target = targetParams;

        const modes = consentConfig.targetModes;
        if (!Array.isArray(modes) || modes.length === 0) return;

        /** @type {TargetProfileDelivery} */
        const delivery = {
            prefixedProfileParams: targetParams,
            profileParameters: stripProfilePrefix(targetParams),
            mboxName: consentConfig.targetMboxName || DEFAULT_MBOX_NAME
        };

        for (const mode of modes) {
            const strategy = TARGET_STRATEGIES[mode];
            if (typeof strategy === "function") {
                try {
                    strategy(delivery);
                } catch (e) {
                    console.warn(`${LOG_PREFIX} Target strategy "${mode}" failed.`, e);
                }
            }
        }
    };

    /**
     * Accumulates a resolved field value into the Target profile params map
     * when the entry defines a `metaNameTarget` key.
     *
     * @param {Record<string, string>} targetParams  Mutable accumulator map.
     * @param {FieldMapEntry}          entry         Field map entry being processed.
     * @param {unknown}                value         Resolved field value (coerced to string).
     */
    const accumulateTargetParam = (targetParams, entry, value) => {
        if (entry.metaNameTarget) {
            const key = `${TARGET_PROFILE_PREFIX}${entry.metaNameTarget}`;
            targetParams[key] = String(value);
        }
    };

    /**
     * Processes a resolved field value for all output channels:
     * emits the 1DS `<meta>` tag and accumulates the Adobe Target
     * profile parameter. Extracted to reduce duplication between
     * the cookie-read (Branch A) and fresh-response (Branch B) paths.
     *
     * @param {FieldMapEntry}          entry        Field map entry for the resolved pointer.
     * @param {unknown}                value        Resolved field value (coerced to string).
     * @param {Record<string, string>} targetParams Mutable accumulator for Target profile params.
     */
    const emitFieldOutputs = (entry, value, targetParams) => {
        emitMetaTagsForEntry(entry, value);
        accumulateTargetParam(targetParams, entry, value);
    };

    /* ---- Branch handlers ---------------------------------------------- */

    /**
     * Branch A: payload is the literal `{"cookie":true}` ESI flag.
     *
     * Reads `oc_db_data` from `document.cookie`. If consent bit is set,
     * publishes hasConsent=true and (when in-scope + fieldMap present)
     * emits `<meta>` tags using values directly from the cookie payload --
     * no JSON-pointer resolution needed since the cookie keys ARE pointers.
     *
     * Crucially, we do NOT write the cookie back here; this branch is a
     * pure read of an existing cookie that the prior page-load wrote.
     *
     * @param {ConsentConfig}  consentConfig
     * @param {FieldMap|null}  fieldMap        Pre-validated config.fieldMap.
     */
    const processExistingCookieBranch = (consentConfig, fieldMap) => {
        const rawCookie = readCookieByName(COOKIE_NAME);
        if (!rawCookie) return; // ESI saw a cookie that has since expired client-side.

        let cookiePayload;
        try {
            cookiePayload = JSON.parse(decodeURIComponent(rawCookie));
        } catch (error) {
            console.warn(`${LOG_PREFIX} oc_db_data cookie unparseable; skipping.`, error);
            return;
        }
        if (!isPlainObject(cookiePayload)) return;
        if (cookiePayload[CONSENT_BIT_KEY] !== CONSENT_BIT_VALUE) return;

        window.serverSideConsent.hasConsent = true;
        if (consentConfig.isInScope !== true || !fieldMap) return;

        /** @type {Record<string, string>} */
        const targetParams = {};

        forEachResolvedField(
            fieldMap,
            (pointer) => cookiePayload[pointer],
            (_pointer, entry, value) => emitFieldOutputs(entry, value, targetParams)
        );

        publishTargetParams(targetParams, consentConfig);
    };

    /**
     * Branch B/C: payload is a fresh response from the lookup or check
     * ESI include endpoint.
     *
     * Publishes `hasConsent` directly from the response. When in-scope and
     * consented, walks the config fieldMap, builds a single pointer-keyed
     * cookie payload, emits `<meta>` tags, and persists the cookie so
     * subsequent navigations are served via Branch A.
     *
     * @param {ConsentResponsePayload} responsePayload
     * @param {ConsentConfig}          consentConfig
     * @param {FieldMap|null}          fieldMap
     * @param {number}                 cookieMaxAgeSeconds
     */
    const processFreshResponseBranch = (responsePayload, consentConfig, fieldMap, cookieMaxAgeSeconds) => {
        window.serverSideConsent.hasConsent = (responsePayload.hasConsent === true);

        // Out-of-scope, no consent, or no map -> nothing to enrich/persist.
        if (consentConfig.isInScope !== true) return;
        if (responsePayload.hasConsent !== true) return;
        if (!fieldMap) return;

        /** @type {ConsentCookiePayload} */
        const cookiePayload = { [CONSENT_BIT_KEY]: CONSENT_BIT_VALUE };

        /** @type {Record<string, string>} */
        const targetParams = {};

        const resolvedCount = forEachResolvedField(
            fieldMap,
            (pointer) => resolveJsonPointer(responsePayload, pointer),
            (pointer, entry, value) => {
                cookiePayload[pointer] = value;
                emitFieldOutputs(entry, value, targetParams);
            }
        );

        if (resolvedCount === 0) return; // Nothing to persist; skip Set-Cookie.
        writeConsentCookie(cookiePayload, cookieMaxAgeSeconds);
        publishTargetParams(targetParams, consentConfig);
    };

    /* ---- Main ---------------------------------------------------------- */

    /**
     * Initializes `window.serverSideConsent.hasConsent` (defaults to `false`)
     * unless callers have already pinned a value or set `disabled === true`.
     *
     * @returns {boolean} `true` when the clientlib should continue, `false` to bail.
     */
    const initialiseConsentContract = () => {
        window.serverSideConsent ??= {};
        if (window.serverSideConsent.disabled === true) return false;
        if (typeof window.serverSideConsent.hasConsent !== "boolean") {
            window.serverSideConsent.hasConsent = false;
        }
        return true;
    };

    if (!initialiseConsentContract()) return;

    try {
        /** @type {ConsentConfig} */
        const consentConfig = parseInlineJsonScript(CONFIG_SCRIPT_ID, true) ?? {};

        const cookieMaxAgeSeconds =
            (typeof consentConfig.cookieMaxAgeSeconds === "number" && consentConfig.cookieMaxAgeSeconds > 0)
                ? consentConfig.cookieMaxAgeSeconds
                : DEFAULT_COOKIE_MAX_AGE_SECONDS;

        const fieldMap = isPlainObject(consentConfig.fieldMap)
            ? /** @type {FieldMap} */ (consentConfig.fieldMap)
            : null;

        /** @type {EmbeddedDataPayload | null} */
        const dataPayload = parseInlineJsonScript(DATA_SCRIPT_ID, false);
        if (!dataPayload) return; // Missing/empty/non-JSON -> hasConsent stays at the init default.

        if (/** @type {CookieFlagPayload} */ (dataPayload).cookie === true) {
            processExistingCookieBranch(consentConfig, fieldMap);
        } else {
            processFreshResponseBranch(
                /** @type {ConsentResponsePayload} */ (dataPayload),
                consentConfig,
                fieldMap,
                cookieMaxAgeSeconds
            );
        }
    } catch (error) {
        // Defensive: a JS error here must NEVER break the page. hasConsent
        // stays at its initialized `false` so trackers stay parked.
        console.warn(`${LOG_PREFIX} Unexpected error in server-side consent client.`, error);
    }
})();
